<?php
declare(strict_types=1);
require __DIR__.'/bootstrap_saas.php';
saas_require_login();
$tourId=saas_require_tour();
saas_require_permission('payment.manage');
$db=saas_db();$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 saas_check_csrf();
 try{
  $action=(string)($_POST['action']??'');
  if($action==='add_payment'){
   $tpId=(int)($_POST['tour_passenger_id']??0);$amount=round((float)($_POST['amount']??0),2);$method=strtoupper(trim((string)($_POST['method']??'CASH')));$ref=trim((string)($_POST['reference']??''));$date=trim((string)($_POST['payment_date']??date('Y-m-d')));$notes=trim((string)($_POST['notes']??''));
   if(!$tpId||$amount<=0)throw new RuntimeException('Passenger and a positive payment amount are required.');
   $allowed=['CASH','BKASH','NAGAD','ROCKET','BANK','CARD','OTHER'];if(!in_array($method,$allowed,true))throw new RuntimeException('Invalid payment method.');
   if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Invalid payment date.');
   $db->beginTransaction();
   $q=$db->prepare("SELECT tp.id,pp.full_name,tp.fee,tp.discount FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id WHERE tp.id=? AND tp.tour_id=? AND tp.status<>'CANCELLED' FOR UPDATE");$q->execute([$tpId,$tourId]);$p=$q->fetch();if(!$p)throw new RuntimeException('Passenger does not belong to this tour.');
   $q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_passenger_id=? AND tour_id=?');$q->execute([$tpId,$tourId]);$paid=(float)$q->fetchColumn();$gross=max(0,(float)$p['fee']-(float)$p['discount']);$due=max(0,$gross-$paid);
   if($amount>$due+0.005)throw new RuntimeException('Payment exceeds the current due amount of '.number_format($due,2).'.');
   $q=$db->prepare('INSERT INTO payments(tour_id,tour_passenger_id,amount,payment_method,reference,payment_date,notes,created_by) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$tourId,$tpId,$amount,$method,$ref?:null,$date,$notes?:null,saas_user_id()]);$id=(int)$db->lastInsertId();$db->commit();
   saas_audit('payment.created','payment',$id,json_encode(['tour_passenger_id'=>$tpId,'amount'=>$amount,'method'=>$method],JSON_UNESCAPED_UNICODE));$ok='Payment recorded for '.$p['full_name'].'.';
  }elseif($action==='delete_payment'){
   $id=(int)($_POST['payment_id']??0);$db->beginTransaction();$q=$db->prepare('SELECT id,amount,tour_passenger_id FROM payments WHERE id=? AND tour_id=? FOR UPDATE');$q->execute([$id,$tourId]);$pay=$q->fetch();if(!$pay)throw new RuntimeException('Payment not found.');$q=$db->prepare('DELETE FROM payments WHERE id=? AND tour_id=?');$q->execute([$id,$tourId]);$db->commit();saas_audit('payment.deleted','payment',$id,json_encode(['amount'=>$pay['amount'],'tour_passenger_id'=>$pay['tour_passenger_id']]));$ok='Payment deleted.';
  }
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}
}
$q=$db->prepare("SELECT tp.id,pp.full_name,pp.phone,tp.fee,tp.discount,COALESCE(SUM(p.amount),0) paid FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id LEFT JOIN payments p ON p.tour_passenger_id=tp.id AND p.tour_id=tp.tour_id WHERE tp.tour_id=? AND tp.status<>'CANCELLED' GROUP BY tp.id,pp.full_name,pp.phone,tp.fee,tp.discount ORDER BY pp.full_name");$q->execute([$tourId]);$passengers=$q->fetchAll();
$q=$db->prepare("SELECT p.*,pp.full_name FROM payments p JOIN tour_passengers tp ON tp.id=p.tour_passenger_id JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id WHERE p.tour_id=? ORDER BY p.payment_date DESC,p.id DESC");$q->execute([$tourId]);$payments=$q->fetchAll();
$totalDue=0;$totalPaid=0;foreach($passengers as $p){$totalPaid+=(float)$p['paid'];$totalDue+=max(0,(float)$p['fee']-(float)$p['discount']-(float)$p['paid']);}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payments</title><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#f4f7fb;margin:0;color:#172033}.wrap{max-width:1200px;margin:25px auto;padding:0 16px}.box{background:#fff;border-radius:16px;padding:20px;margin-bottom:18px;box-shadow:0 6px 22px #0000000b}.grid{display:grid;grid-template-columns:350px 1fr;gap:18px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}label{display:block;font-size:13px;font-weight:700;margin:10px 0 5px}input,select,textarea,button{width:100%;padding:10px;border:1px solid #d0d5dd;border-radius:9px;font:inherit}textarea{min-height:65px;resize:vertical}button{margin-top:12px;background:#155eef;color:#fff;border-color:#155eef;cursor:pointer;font-weight:700}.msg{padding:11px;border-radius:9px;margin-bottom:15px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.stat{border:1px solid #eaecf0;border-radius:12px;padding:14px}.stat b{display:block;font-size:22px;margin-top:5px}.muted{color:#667085;font-size:13px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #eee;text-align:left;white-space:nowrap}.tablewrap{overflow:auto}.due{font-weight:700}.paid{color:#067647}.smallbtn{padding:6px 9px;margin:0;background:#fff;color:#b42318;border-color:#fecdca;font-size:12px}.history{margin-top:18px}@media(max-width:850px){.grid{grid-template-columns:1fr}.fields{grid-template-columns:1fr}.stats{grid-template-columns:1fr}}
</style></head><body><main class="wrap"><p><a href="saas_dashboard.php">← Dashboard</a></p><h1>Payments</h1><?php if($ok):?><div class="msg ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=saas_h($error)?></div><?php endif;?><section class="box stats"><div class="stat"><span class="muted">Total received</span><b><?=number_format($totalPaid,2)?></b></div><div class="stat"><span class="muted">Total outstanding</span><b><?=number_format($totalDue,2)?></b></div></section><div class="grid"><section class="box"><h2>Record payment</h2><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="add_payment"><label>Passenger</label><select name="tour_passenger_id" required><option value="">Select passenger</option><?php foreach($passengers as $p):$due=max(0,(float)$p['fee']-(float)$p['discount']-(float)$p['paid']);?><option value="<?=$p['id']?>" <?=($due<=0?'disabled':'')?>><?=saas_h($p['full_name'])?> — Due <?=number_format($due,2)?></option><?php endforeach;?></select><div class="fields"><div><label>Amount</label><input type="number" name="amount" min="0.01" step="0.01" required></div><div><label>Date</label><input type="date" name="payment_date" value="<?=date('Y-m-d')?>" required></div></div><div class="fields"><div><label>Method</label><select name="method"><option>CASH</option><option>BKASH</option><option>NAGAD</option><option>ROCKET</option><option>BANK</option><option>CARD</option><option>OTHER</option></select></div><div><label>Reference</label><input name="reference" placeholder="Txn / receipt no."></div></div><label>Notes</label><textarea name="notes"></textarea><button>Save payment</button></form></section><section class="box"><h2>Passenger balances</h2><div class="tablewrap"><table><tr><th>Passenger</th><th>Fee</th><th>Discount</th><th>Paid</th><th>Due</th></tr><?php foreach($passengers as $p):$due=max(0,(float)$p['fee']-(float)$p['discount']-(float)$p['paid']);?><tr><td><?=saas_h($p['full_name'])?><div class="muted"><?=saas_h($p['phone']??'')?></div></td><td><?=number_format((float)$p['fee'],2)?></td><td><?=number_format((float)$p['discount'],2)?></td><td class="paid"><?=number_format((float)$p['paid'],2)?></td><td class="due"><?=number_format($due,2)?></td></tr><?php endforeach;?></table></div></section></div><section class="box history"><h2>Payment history</h2><div class="tablewrap"><table><tr><th>Date</th><th>Passenger</th><th>Amount</th><th>Method</th><th>Reference</th><th></th></tr><?php foreach($payments as $p):?><tr><td><?=saas_h($p['payment_date'])?></td><td><?=saas_h($p['full_name'])?></td><td><?=number_format((float)$p['amount'],2)?></td><td><?=saas_h($p['payment_method']??'')?></td><td><?=saas_h($p['reference']??'')?></td><td><form method="post" onsubmit="return confirm('Delete this payment?')"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="delete_payment"><input type="hidden" name="payment_id" value="<?=$p['id']?>"><button class="smallbtn">Delete</button></form></td></tr><?php endforeach;?></table><?php if(!$payments):?><p class="muted">No payments recorded yet.</p><?php endif;?></div></section></main></body></html>
